#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int h, w;
    scanf("%d %d", &h, &w);
    getchar();

    int mass_count = 0;
    int column_sum = 0;
    int support = 0;
    char line[502];

    for (int row = 0; row < h; row++) {
        fgets(line, sizeof(line), stdin);
        for (int column = 0; column < w; column++) {
            if (line[column] == '#') {
                mass_count++;
                column_sum += column;
            } else if (line[column] == 'X') {
                support = column;
            }
        }
    }

    // The center of mass is column_sum / mass_count.
    // Balance requires its distance from the support center to be at most 0.5:
    // abs(column_sum / mass_count - support) <= 0.5.
    // Multiply by 2 * mass_count to compare integers exactly:
    // abs(2 * column_sum - 2 * support * mass_count) <= mass_count.
    int balanced = abs(2 * column_sum - 2 * support * mass_count) <= mass_count;

    printf("%d %.6f\n", support, (double) column_sum / mass_count);
    puts(balanced ? "In balance" : "Not in balance");
    return 0;
}
